CREATE OR REPLACE FUNCTION public.strategy_analytics_hold_computed_at_until_success()
RETURNS TRIGGER
LANGUAGE plpgsql
SET search_path = public, pg_catalog
AS $$
BEGIN
  IF NEW.computation_status IN ('failed', 'computing') THEN
    NEW.computed_at := OLD.computed_at;
  END IF;
  RETURN NEW;
END;
$$;
